#!/usr/bin/env bash
# Local CI: the same checks .github/workflows/ci.yml runs, on your own machine.
# Generated by agent-ready. Keep the two in step: if a check matters enough to
# block a merge, it belongs in both. Deploys and remote D1 commands never run here.
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"

step() { printf '\n==> %s\n' "$*"; }

step "Install (from lockfile)"; npm ci --no-audit --no-fund
step "Typecheck"; npm run typecheck
step "Tests"; npm test

echo
echo "Local CI passed."
